import { useEffect, useId, useRef } from 'react';
import './MasterDetailDialog.css';
type Item = { id: string; title: string; summary: string; metadata: { label: string; value: string }[] };
export function MasterDetailDialog({ open, items, selectedId, onSelect, onClose, onConfirm }: { open: boolean; items: Item[]; selectedId: string | null; onSelect: (id: string) => void; onClose: () => void; onConfirm: (id: string) => void }) {
 const dialog = useRef<HTMLDialogElement>(null);
 const id = useId();
 const selected = items.find(item => item.id === selectedId);
 useEffect(() => { const node = dialog.current!; if (open && !node.open) { const previous = document.activeElement as HTMLElement | null; node.showModal(); return () => { node.close(); previous?.focus(); }; } if (!open && node.open) node.close(); }, [open]);
 return <dialog ref={dialog} className="detail-dialog" aria-labelledby={id + '-title'} aria-describedby={id + '-summary'} onCancel={event => { event.preventDefault(); onClose(); }}>
 <header><h2 id={id + '-title'}>Choose an item</h2><p id={id + '-summary'}>Select an item to review its details before continuing.</p><button onClick={onClose} aria-label="Close item dialog">Close</button></header>
 <div className="master-detail">
 <fieldset><legend>Items</legend>{items.length ? items.map(item => <label key={item.id}><input type="radio" name={id + '-item'} checked={item.id === selectedId} onChange={() => onSelect(item.id)} />{item.title}</label>) : <p>No items available.</p>}</fieldset>
 <section aria-label="Selected item details" aria-live="polite">{selected ? <><h3>{selected.title}</h3><p>{selected.summary}</p><dl>{selected.metadata.map((entry, index) => <div key={index}><dt>{entry.label}</dt><dd>{entry.value}</dd></div>)}</dl></> : <p>Select an item to see its details.</p>}</section>
 </div><footer><button onClick={onClose}>Cancel</button><button disabled={!selected} onClick={() => selected && onConfirm(selected.id)}>Continue</button></footer>
 </dialog>;
}

