.detail-dialog{box-sizing:border-box;width:min(800px,calc(100vw - 24px));max-height:calc(100dvh - 24px);overflow:auto;border:1px solid #767c87;border-radius:12px;padding:20px}
.detail-dialog::backdrop{background:#0008}
.master-detail{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,2fr);gap:24px;margin-block:20px}
.master-detail>*{min-width:0;overflow-wrap:anywhere}
.master-detail fieldset{margin:0;padding:12px}
.master-detail label{display:flex;gap:8px;align-items:baseline;padding-block:8px}
.master-detail dl div{margin-bottom:12px}.master-detail dt{font-weight:700}.master-detail dd{margin:4px 0 0}
.detail-dialog footer{display:flex;gap:8px;justify-content:flex-end;flex-wrap:wrap}
.detail-dialog :focus-visible{outline:2px solid #255ec9;outline-offset:2px}
@media(max-width:560px){.master-detail{grid-template-columns:minmax(0,1fr)}}
